CREATE TABLE users (
  id INT PRIMARY KEY,
  name VARCHAR(50),
  email VARCHAR(100),
  age INT,
  INDEX idx_age_email (age, email)
);

-- Query A
SELECT email FROM users WHERE age = 30;

-- Query B
SELECT name FROM users WHERE age = 30;

-- Table has 1,000,000 rows
-- 'status' has only two values: 'Active' (900,000 rows), 'Inactive' (100,000 rows)
CREATE INDEX idx_status ON users(status);

SELECT * FROM users WHERE status = 'Active';

CREATE TABLE orders (
  user_id INT,
  order_date DATETIME,
  amount DECIMAL,
  INDEX idx_user_date (user_id, order_date)
);
